/**
 * AutoNPC derin denetim ağı — @minecraft/server MOCK'u.
 * Amaç: addon'u Minecraft OLMADAN boot edip sanal voxel dünyasında koşturmak.
 * Gerçek cihaz davranışını taklit eder: chatSend before-event'i STABIL API'DE
 * OLMADIĞI için subscribe'ı varsayılan FIRLATIR (kök neden regresyon kapanı).
 */

export const __mock = {
  currentTick: 0,
  intervals: [],
  timeouts: [],
  runQueue: [],
  dims: new Map(),
  entities: new Set(),
  chat: [],
  flags: { chatSendBeta: true }, // gerçek stabil istemci davranışı
  worldGen: (x, y, z) => (y === 63 ? "minecraft:grass_block" : y < 63 ? "minecraft:stone" : "minecraft:air"),
  dropResolver: (id) => id,
  nextId: 1,
  blockReads: 0,
  blockReadStats: { max: 0, total: 0, ticks: 0 },
  tick(steps = 1) {
    for (let s = 0; s < steps; s++) {
      this.currentTick++;
      this.blockReads = 0;
      const due = this.timeouts.filter((t) => t.at <= this.currentTick);
      this.timeouts = this.timeouts.filter((t) => t.at > this.currentTick);
      for (const t of due) safeCall(t.fn);
      for (const iv of this.intervals) {
        if ((this.currentTick - iv.start) % iv.every === 0) safeCall(iv.fn);
      }
      while (this.runQueue.length) safeCall(this.runQueue.shift());
      this.blockReadStats.max = Math.max(this.blockReadStats.max, this.blockReads);
      this.blockReadStats.total += this.blockReads;
      this.blockReadStats.ticks++;
    }
  },
  reset() {
    this.intervals = [];
    this.timeouts = [];
    this.runQueue = [];
    this.entities.clear();
    this.dims.clear();
    this.currentTick = 0;
  },
};

export const __errors = [];
function safeCall(fn) {
  try { fn(); } catch (e) { __errors.push(String(e?.stack || e)); }
}

function key(x, y, z) { return `${x},${y},${z}`; }

class EventSignal {
  constructor(name, throws = false) { this.name = name; this.handlers = []; this.throws = throws; }
  subscribe(fn) {
    if (this.throws) throw new Error(`'${this.name}' yalnız BETA API'de mevcut (mock)`);
    this.handlers.push(fn);
    return fn;
  }
  unsubscribe(fn) { this.handlers = this.handlers.filter((h) => h !== fn); }
  fire(ev) { for (const h of this.handlers) h(ev); }
}

export class ItemStack {
  constructor(typeId, amount = 1) { this.typeId = typeId; this.amount = amount; this.nameTag = undefined; }
  setLore(l) { this.lore = l; }
}

export const EquipmentSlot = { Head: "Head", Chest: "Chest", Legs: "Legs", Feet: "Feet", Mainhand: "Mainhand", Offhand: "Offhand" };
export const EntityDamageCause = { entityAttack: "entityAttack", entityExplosion: "entityExplosion", blockExplosion: "blockExplosion", projectile: "projectile", fall: "fall" };

class Container {
  constructor(size = 36) { this.slots = new Array(size).fill(undefined); }
  get size() { return this.slots.length; }
  getItem(i) { return this.slots[i]; }
  setItem(i, s) { this.slots[i] = s; }
  addItem(stack) {
    for (let i = 0; i < this.slots.length; i++) {
      if (!this.slots[i]) { this.slots[i] = stack; return undefined; }
    }
    return stack; // dolu
  }
}

class Block {
  constructor(dim, x, y, z) { this.dim = dim; this.x = x; this.y = y; this.z = z; }
  get typeId() { return this.dim.getBlockId(this.x, this.y, this.z); }
  get location() { return { x: this.x, y: this.y, z: this.z }; }
  setType(id) { this.dim.setBlockId(this.x, this.y, this.z, id); }
  getComponent(name) {
    if (name === "minecraft:inventory" && (this.typeId === "minecraft:chest" || this.typeId === "minecraft:barrel")) {
      const k = key(this.x, this.y, this.z);
      if (!this.dim.containers.has(k)) this.dim.containers.set(k, { container: new Container(27) });
      return this.dim.containers.get(k);
    }
    return undefined;
  }
}

export class Entity {
  constructor(typeId, location, dimension) {
    this.id = "ent_" + (__mock.nextId++);
    this.typeId = typeId;
    this.location = { ...location };
    this.dimension = dimension;
    this.nameTag = "";
    this.tags = new Set();
    this.props = new Map();
    this.rotation = { x: 0, y: 0 };
    this.health = { max: typeId === "autonpc:worker" ? 40 : 10, cur: typeId === "autonpc:worker" ? 40 : 10 };
    this.equipment = new Map();
    this.dead = false;
    __mock.entities.add(this);
  }
  addTag(t) { this.tags.add(t); }
  hasTag(t) { return this.tags.has(t); }
  getDynamicProperty(k) { return this.props.get(k); }
  setDynamicProperty(k, v) { this.props.set(k, v); }
  teleport(loc, opts = {}) {
    this.location = { x: loc.x, y: loc.y, z: loc.z };
    if (opts.dimension) this.dimension = opts.dimension;
    if (opts.rotation) this.rotation = { ...opts.rotation };
  }
  tryTeleport(loc, opts = {}) { this.teleport(loc, opts); return true; }
  applyImpulse() { /* fizik yok */ }
  applyKnockback() { /* fizik yok */ }
  playAnimation() { /* görsel yok */ }
  getViewDirection() { return { x: 1, y: 0, z: 0 }; }
  remove() { this.dead = true; __mock.entities.delete(this); }
  applyDamage(n, opts = {}) {
    const self = this;
    this.health.cur -= n;
    world.afterEvents.entityHurt.fire({ hurtEntity: self, damage: n, damageSource: { cause: opts.cause ?? "entityAttack" } });
    if (this.health.cur <= 0) {
      // ölüm ganimeti (vanilla loot benzetimi): hayvan/canavar item bırakır
      if (this.typeId !== "minecraft:player" && this.typeId !== "autonpc:worker" && this.typeId !== "minecraft:item") {
        const loot = { "minecraft:cow": "minecraft:leather", "minecraft:sheep": "minecraft:wool", "minecraft:chicken": "minecraft:feather", "minecraft:spider": "minecraft:string" }[this.typeId] ?? "minecraft:bone";
        this.dimension.spawnItem(new ItemStack(loot, 1), { ...this.location });
      }
      this.remove();
    }
    return true;
  }
  getComponent(name) {
    if (name === "minecraft:health") {
      const h = this.health;
      return { get currentValue() { return h.cur; }, get effectiveMax() { return h.max; }, setCurrentValue: (v) => { h.cur = v; } };
    }
    if (name === "minecraft:equippable") {
      return { setEquipment: (slot, stack) => { this.equipment.set(slot, stack); } };
    }
    if (name === "minecraft:item" && this.typeId === "minecraft:item") return { itemStack: this.itemStack };
    if (name === "minecraft:inventory" && this.typeId === "minecraft:player") {
      if (!this._inv) this._inv = { container: new Container(36) };
      return this._inv;
    }
    if (name === "minecraft:projectile") {
      return { owner: undefined, shoot: () => { /* balistik yok */ } };
    }
    return undefined;
  }
  runCommand(cmd) { return this.dimension.runCommand(cmd); }
}

class Player extends Entity {
  constructor(name, location, dimension) {
    super("minecraft:player", location, dimension);
    this.name = name;
    this.selectedSlotIndex = 0;
    this.messages = [];
  }
  sendMessage(m) { this.messages.push(m); __mock.chat.push(`[${this.name}] ${m}`); }
}

class Dimension {
  constructor(id) {
    this.id = id;
    this.blocks = new Map(); // override'lar; geri kalanı worldGen
    this.containers = new Map();
  }
  getBlockId(x, y, z) {
    const o = this.blocks.get(key(x, y, z));
    return o !== undefined ? o : __mock.worldGen(x, y, z, this.id);
  }
  setBlockId(x, y, z, id) { this.blocks.set(key(x, y, z), id); }
  getBlock(p) {
    __mock.blockReads++;
    const x = Math.floor(p.x), y = Math.floor(p.y), z = Math.floor(p.z);
    if (y < -64 || y > 320) return undefined;
    return new Block(this, x, y, z);
  }
  getEntities(opts = {}) {
    const out = [];
    for (const e of __mock.entities) {
      if (e.dimension !== this || e.dead) continue;
      if (opts.type && e.typeId !== opts.type) continue;
      if (opts.location && opts.maxDistance !== undefined) {
        const dx = e.location.x - opts.location.x, dy = (e.location.y ?? 0) - (opts.location.y ?? 0), dz = e.location.z - opts.location.z;
        if (Math.sqrt(dx * dx + dy * dy + dz * dz) > opts.maxDistance) continue;
      }
      out.push(e);
    }
    return out;
  }
  spawnEntity(typeId, loc) { return new Entity(typeId, loc, this); }
  spawnItem(stack, loc) {
    const e = new Entity("minecraft:item", loc, this);
    e.itemStack = stack;
    return e;
  }
  playSound() { /* ses yok */ }
  spawnParticle() { /* partikül yok */ }
  createExplosion(loc, r) {
    const R = Math.ceil(r);
    for (let dx = -R; dx <= R; dx++) for (let dy = -R; dy <= R; dy++) for (let dz = -R; dz <= R; dz++) {
      if (dx * dx + dy * dy + dz * dz > r * r) continue;
      const x = Math.floor(loc.x + dx), y = Math.floor(loc.y + dy), z = Math.floor(loc.z + dz);
      if (this.getBlockId(x, y, z) !== "minecraft:bedrock") this.setBlockId(x, y, z, "minecraft:air");
    }
    return true;
  }
  runCommand(cmd) {
    const t = String(cmd).trim().split(/\s+/);
    if (t[0] === "setblock") {
      const [x, y, z] = [Number(t[1]), Number(t[2]), Number(t[3])];
      let id = t[4] || "air";
      if (!id.includes(":")) id = "minecraft:" + id.split("[")[0];
      const prev = this.getBlockId(x, y, z);
      this.setBlockId(x, y, z, id.split("[")[0]);
      if (t[5] === "destroy" && prev !== "minecraft:air") {
        const drop = __mock.dropResolver(prev);
        if (drop && drop !== "minecraft:air") this.spawnItem(new ItemStack(drop, 1), { x: x + 0.5, y: y + 0.5, z: z + 0.5 });
      }
      return { successCount: 1 };
    }
    if (t[0] === "playsound" || t[0] === "particle" || t[0] === "say") return { successCount: 1 };
    throw new Error("mock: bilinmeyen komut " + t[0]);
  }
}

export const world = {
  afterEvents: {
    playerSpawn: new EventSignal("playerSpawn"),
    itemUse: new EventSignal("itemUse"),
    entityHurt: new EventSignal("entityHurt"),
  },
  beforeEvents: {
    playerInteractWithEntity: new EventSignal("playerInteractWithEntity"),
    playerInteractWithBlock: new EventSignal("playerInteractWithBlock"),
    get chatSend() {
      if (__mock.flags.chatSendBeta) {
        return { subscribe() { throw new Error("'chatSend' before-event yalnız BETA API'de mevcut (mock/stabil istemci)"); } };
      }
      if (!this._chat) this._chat = new EventSignal("chatSend");
      return this._chat;
    },
  },
  getDimension(id) {
    const norm = id.replace("minecraft:", "");
    if (!__mock.dims.has(norm)) __mock.dims.set(norm, new Dimension(norm));
    return __mock.dims.get(norm);
  },
  getAllPlayers() { return [...__mock.entities].filter((e) => e.typeId === "minecraft:player" && !e.dead); },
  sendMessage(m) { __mock.chat.push(`[WORLD] ${m}`); },
};

export const system = {
  afterEvents: { scriptEventReceive: new EventSignal("scriptEventReceive") },
  get currentTick() { return __mock.currentTick; },
  run(fn) { __mock.runQueue.push(fn); },
  runTimeout(fn, t = 1) { __mock.timeouts.push({ fn, at: __mock.currentTick + t }); },
  runInterval(fn, every = 1) { __mock.intervals.push({ fn, every: Math.max(1, every), start: __mock.currentTick }); return __mock.intervals.length; },
};

export function __makePlayer(name, loc, dim) { return new Player(name, loc, dim); }
